+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem;
+    border-radius: 3px;
+}
+
+::deep .emoji-option:hover {
+    background: #4f545c;
+}
+
+/* Message input */
+::deep .message-input {
+    display: flex;
+    gap: 0.5rem;
+    padding: 0.75rem 1rem;
+    border-top: 1px solid #202225;
+    flex-shrink: 0;
+}
+
+::deep .message-input textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 4px;
+    padding: 0.5rem 0.75rem;
+    color: #dcddde;
+    font-size: 0.9rem;
+    resize: none;
+    outline: none;
+    font-family: inherit;
+}
+
+::deep .message-input textarea::placeholder {
+    color: #72767d;
+}
+
+::deep .send-button {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    padding: 0.5rem 1rem;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+    align-self: flex-end;
+}
+
+::deep .send-button:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-button:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+.chat-thread {
+    width: 25%;
+    min-width: 250px;
+    background: #2f3136;
+    color: #dcddde;
+    border-left: 1px solid #202225;
+    display: flex;
+    flex-direction: column;
+}
+
+::deep .thread-panel {
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #b9bbbe;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.4rem;
+    border-radius: 3px;
+}
+
+::deep .close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #202225;
+    background: #36393f;
+}
+
+::deep .thread-root-message .message-content {
+    margin-top: 0.3rem;
+    font-size: 0.85rem;
+    color: #b9bbbe;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+}
+
+::deep .thread-reply {
+    padding: 0.4rem 0;
+    border-bottom: 1px solid #36393f;
+}
+
+::deep .thread-reply:last-child {
+    border-bottom: none;
+}
+

